<script setup>
import {Head,useForm,usePage} from '@inertiajs/vue3';import {computed,ref} from 'vue';import TurnstileWidget from '../../Components/TurnstileWidget.vue';
const page=usePage(),turnstile=ref(null),security=computed(()=>page.props.security||{}),csrf=document.querySelector('meta[name="csrf-token"]')?.getAttribute('content')||'',form=useForm({_token:csrf,email:'',password:'',turnstile_token:''});const submit=()=>form.post('/admin/login',{onFinish:()=>{form.reset('password');turnstile.value?.reset()}});
</script><template><Head title="Masuk Admin"/><main class="min-h-screen bg-[#07172d] p-4 text-slate-900"><div class="mx-auto grid min-h-[calc(100vh-2rem)] max-w-[980px] place-items-center"><form class="w-full max-w-[390px] rounded-xl border border-slate-200 bg-white p-6 shadow-2xl" @submit.prevent="submit"><div class="mb-5 flex items-center gap-3"><span class="lf-admin-logo">LF</span><div><h1 class="m-0 text-[18px] font-black text-[#0c1c3b]">LFAMILIA ADMIN</h1><span class="sr-only">Admin LFAMILIA</span><p class="m-0 text-[9px] text-slate-500">Top Up Game Solution</p></div></div><div class="grid gap-3"><label class="text-[10px] font-semibold text-slate-600">Email<input v-model="form.email" type="email" required class="mt-1 h-9 w-full rounded-md border border-slate-200 px-3 text-[11px] outline-none focus:border-[#1769e8]"></label><label class="text-[10px] font-semibold text-slate-600">Kata sandi<input v-model="form.password" type="password" required class="mt-1 h-9 w-full rounded-md border border-slate-200 px-3 text-[11px] outline-none focus:border-[#1769e8]"></label><p v-if="Object.keys(form.errors).length" role="alert" class="text-sm text-red-600">{{ Object.values(form.errors)[0] }}</p><TurnstileWidget v-if="security.turnstile_required" ref="turnstile" :site-key="security.turnstile_site_key" :action="security.turnstile_action" @token="form.turnstile_token=$event"/><button class="h-9 rounded-md bg-[#1769e8] text-[11px] font-black text-white" :disabled="form.processing">Masuk</button></div></form></div></main></template>